import sys
import json
import math
from decimal import Decimal, ROUND_HALF_UP


def round_half_up(value, decimals=2):
    """Round a float to given number of decimal places using round-half-up."""
    quantize_str = '0.' + '0' * decimals
    return float(Decimal(str(value)).quantize(Decimal(quantize_str), rounding=ROUND_HALF_UP))


def compute_invoice_total(invoice_data):
    """
    Validates invoice_data and computes subtotal, discount, tax, total.
    Returns a dict with result or error.
    """
    if not isinstance(invoice_data, dict):
        return {"error": "Input must be a JSON object"}

    # Validate top-level keys
    if "lines" not in invoice_data or not isinstance(invoice_data["lines"], list):
        return {"error": "Missing or invalid 'lines' (must be an array)"}
    if "discount_percent" not in invoice_data or not isinstance(invoice_data["discount_percent"], (int, float)):
        return {"error": "Missing or invalid 'discount_percent' (must be a number)"}
    if "tax_percent" not in invoice_data or not isinstance(invoice_data["tax_percent"], (int, float)):
        return {"error": "Missing or invalid 'tax_percent' (must be a number)"}

    lines = invoice_data["lines"]
    discount_percent = invoice_data["discount_percent"]
    tax_percent = invoice_data["tax_percent"]

    # Validate each line
    for i, line in enumerate(lines):
        if not isinstance(line, dict):
            return {"error": f"Line {i} is not an object"}
        if "description" not in line or not isinstance(line["description"], str):
            return {"error": f"Line {i}: missing or invalid 'description' (must be a string)"}
        if "quantity" not in line or not isinstance(line["quantity"], (int, float)):
            return {"error": f"Line {i}: missing or invalid 'quantity' (must be a number)"}
        if "unit_price" not in line or not isinstance(line["unit_price"], (int, float)):
            return {"error": f"Line {i}: missing or invalid 'unit_price' (must be a number)"}

        if line["quantity"] < 0:
            return {"error": f"Line {i}: negative quantity"}
        if line["unit_price"] < 0:
            return {"error": f"Line {i}: negative unit_price"}

    # Validate percent ranges
    if not (0 <= discount_percent <= 100):
        return {"error": "discount_percent out of range (0-100)"}
    if not (0 <= tax_percent <= 50):
        return {"error": "tax_percent out of range (0-50)"}

    # Compute subtotal
    subtotal = sum(line["quantity"] * line["unit_price"] for line in lines)
    subtotal = round_half_up(subtotal, 2)

    # Compute discount
    discount = subtotal * (discount_percent / 100)
    discount = round_half_up(discount, 2)

    # Compute discounted amount
    discounted_amount = subtotal - discount

    # Compute tax
    tax = discounted_amount * (tax_percent / 100)
    tax = round_half_up(tax, 2)

    # Compute total
    total = subtotal - discount + tax
    total = round_half_up(total, 2)

    return {
        "subtotal": subtotal,
        "discount": discount,
        "tax": tax,
        "total": total
    }


def main():
    input_text = sys.stdin.read()
    try:
        data = json.loads(input_text)
    except json.JSONDecodeError as e:
        print(json.dumps({"error": f"Invalid JSON: {e}"}))
        return
    result = compute_invoice_total(data)
    print(json.dumps(result))


if __name__ == "__main__":
    main()

import sys
import os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

import json
import pytest
from invoice_calculator import compute_invoice_total, round_half_up


class TestComputeInvoiceTotal:
    def test_happy_path(self):
        data = {
            "lines": [
                {"description": "item1", "quantity": 2, "unit_price": 10.00},
                {"description": "item2", "quantity": 1, "unit_price": 5.50}
            ],
            "discount_percent": 10,
            "tax_percent": 20
        }
        result = compute_invoice_total(data)
        assert "subtotal" in result
        assert "discount" in result
        assert "tax" in result
        assert "total" in result
        assert result["subtotal"] == 25.5
        assert result["discount"] == 2.55
        assert result["tax"] == 4.59
        assert result["total"] == 27.54

    def test_negative_quantity(self):
        data = {
            "lines": [
                {"description": "item", "quantity": -1, "unit_price": 10.0}
            ],
            "discount_percent": 0,
            "tax_percent": 0
        }
        result = compute_invoice_total(data)
        assert "error" in result
        assert "quantity" in result["error"]

    def test_discount_out_of_range(self):
        data = {
            "lines": [
                {"description": "item", "quantity": 1, "unit_price": 100.0}
            ],
            "discount_percent": 110,
            "tax_percent": 0
        }
        result = compute_invoice_total(data)
        assert "error" in result
        assert "discount_percent" in result["error"]

    def test_tax_out_of_range(self):
        data = {
            "lines": [
                {"description": "item", "quantity": 1, "unit_price": 100.0}
            ],
            "discount_percent": 0,
            "tax_percent": 60
        }
        result = compute_invoice_total(data)
        assert "error" in result
        assert "tax_percent" in result["error"]

    def test_negative_unit_price(self):
        data = {
            "lines": [
                {"description": "item", "quantity": 1, "unit_price": -5.0}
            ],
            "discount_percent": 0,
            "tax_percent": 0
        }
        result = compute_invoice_total(data)
        assert "error" in result
        assert "unit_price" in result["error"]

    def test_missing_lines(self):
        data = {"discount_percent": 0, "tax_percent": 0}
        result = compute_invoice_total(data)
        assert "error" in result
        assert "lines" in result["error"]

    def test_round_half_up(self):
        assert round_half_up(2.345, 2) == 2.35
        assert round_half_up(2.344, 2) == 2.34
        assert round_half_up(2.5, 0) == 3.0
        assert round_half_up(1.999, 2) == 2.0

    def test_multiple_lines(self):
        data = {
            "lines": [
                {"description": "a", "quantity": 3, "unit_price": 1.25},
                {"description": "b", "quantity": 2, "unit_price": 0.99}
            ],
            "discount_percent": 0,
            "tax_percent": 0
        }
        result = compute_invoice_total(data)
        # subtotal = 3*1.25 + 2*0.99 = 3.75 + 1.98 = 5.73
        assert result["subtotal"] == 5.73
        assert result["discount"] == 0
        assert result["tax"] == 0
        assert result["total"] == 5.73

    def test_non_digit_input(self):
        result = compute_invoice_total("not a dict")
        assert "error" in result
        assert "Input must be a JSON object" in result["error"]
